def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = []
    prev_bids = []
    urgent_opp = 0
    rich_opp = 0

    for opp in opponents_status.values():
        if opp.get('alive'):
            alive_opponents.append(opp)
            if opp.get('budget', 0) >= DAILY_SALARY * 2:
                rich_opp += 1
            if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 2:
                urgent_opp += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                prev_bids.append(prev.get('bid', 0))

    if not alive_opponents:
        if hp <= 3 or no_water_days >= 2:
            return max(0, min(budget, 28.0))
        return max(0, min(budget, 8.0))

    tightness = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    base = DAILY_SALARY * (0.42 + 0.18 * tightness)

    if prev_bids:
        highest_prev = max(prev_bids)
        avg_prev = sum(prev_bids) / float(len(prev_bids))
    else:
        highest_prev = 0.0
        avg_prev = 0.0

    if hp <= 2 or no_water_days >= 2:
        bid = max(base + 18.0, highest_prev + 2.0, DAILY_SALARY * 0.88)
    elif hp <= 4 or no_water_days >= 1:
        bid = max(base + 8.0, avg_prev + 2.0, DAILY_SALARY * 0.62)
    else:
        if highest_prev >= DAILY_SALARY * 0.9:
            bid = DAILY_SALARY * 0.28
        elif highest_prev >= DAILY_SALARY * 0.75:
            bid = max(DAILY_SALARY * 0.38, avg_prev - 6.0)
        elif highest_prev > 0:
            bid = max(base, highest_prev + 1.5)
        else:
            bid = base

    bid += min(6.0, urgent_opp * 1.5)
    bid += min(4.0, rich_opp * 0.8)

    if supply >= 22:
        bid -= 6.0
    elif supply <= 17:
        bid += 5.0

    reserve_floor = 0.0
    if hp > 4 and no_water_days == 0:
        reserve_floor = min(12.0, budget * 0.18)

    bid = min(bid, max(0.0, budget - reserve_floor))
    bid = max(0.0, min(budget, bid))
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90

    supply = float(day_context.get('supply', 0.0))
    day = day_context.get('day', 0)

    # Basic sanity
    budget = float(my_status.get('budget', 0.0))
    hp = int(my_status.get('hp', 0))

    alive_opponents = []
    for opp_id, opp in opponents_status.items():
        if opp is not None and opp.get('alive', False):
            alive_opponents.append((opp_id, opp))

    # If no opponents, take a safe amount
    if not alive_opponents:
        target = 0.55 * DAILY_SALARY
        return max(0.0, min(budget, target))

    # Read yesterday bids from previous_trace only (immediate reaction)
    prev_bids = []
    for _, opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if isinstance(prev, dict) and prev.get('bid') is not None:
            prev_bids.append(float(prev.get('bid')))

    # Estimate competitive pressure
    if prev_bids:
        highest_prev_bid = max(prev_bids)
        lowest_prev_bid = min(prev_bids)
    else:
        highest_prev_bid = 0.0
        lowest_prev_bid = 0.0

    # Supply-aware aggressiveness: if supply is scarce relative to requirement, bid more.
    # Avoid list indexing; only compute scalars.
    scarcity_ratio = 0.0
    if WATER_REQ > 0:
        scarcity_ratio = supply / float(WATER_REQ)

    # Base bid: mid level to avoid overpaying
    base_bid = 0.45 * DAILY_SALARY
    if scarcity_ratio < 2.0:
        base_bid = 0.60 * DAILY_SALARY
    elif scarcity_ratio > 2.5:
        base_bid = 0.40 * DAILY_SALARY

    # React to opponents' yesterday behavior
    if prev_bids:
        # If someone previously overbid heavily, we need to compete but not max out.
        if highest_prev_bid >= 0.85 * DAILY_SALARY:
            if hp >= 4:
                bid = min(0.75 * DAILY_SALARY, highest_prev_bid - 1.0)
            else:
                bid = min(0.95 * DAILY_SALARY, highest_prev_bid - 0.5)
        else:
            # If bids were modest, slightly over the lowest to secure water.
            # Add a small increment to beat typical low bids.
            bid = max(base_bid, lowest_prev_bid + 1.5)
    else:
        bid = base_bid

    # HP risk management: low HP increases bid
    if hp <= 2:
        bid = max(bid, 0.85 * DAILY_SALARY)
    elif hp == 3:
        bid = max(bid, 0.65 * DAILY_SALARY)

    # Budget cap
    bid = float(bid)
    if budget <= 0.0:
        return 0.0

    # Also cap by plausible daily salary-like scale
    bid = min(bid, DAILY_SALARY)
    return max(0.0, min(budget, bid))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    CRITICAL_HP_THRESHOLD = 2
    MODERATE_HP_THRESHOLD = 4

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    # If no opponents, bid minimally to get water
    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.3)

    # Collect yesterday's bids from alive opponents
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    # Calculate total water demand (including myself)
    total_water_demand = WATER_REQ
    for opp in alive_opponents:
        total_water_demand += opp['water_requirement']

    # --- Bidding Logic ---

    # 1. Desperation Mode (Critical HP)
    if my_status['hp'] <= CRITICAL_HP_THRESHOLD:
        return min(my_status['budget'], DAILY_SALARY * 0.95)

    # 2. Supply is very abundant - enough for everyone to get their full requirement
    if day_context['supply'] >= total_water_demand:
        bid = DAILY_SALARY * 0.4 # Base bid for abundant supply
        if yesterday_bids:
            highest_prev_bid = max(yesterday_bids)
            if highest_prev_bid > DAILY_SALARY * 0.5:
                bid = max(bid, highest_prev_bid * 0.9) # Slightly less than highest if it was high
            else:
                bid = max(bid, highest_prev_bid + 1) # Just slightly above if it was low
        return min(my_status['budget'], bid)

    # 3. Moderate HP or Scarce/Normal Supply
    current_bid = DAILY_SALARY * 0.55 # Default bid for normal conditions

    # Adjust based on yesterday's bids
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
        avg_prev_bid = sum(yesterday_bids) / len(yesterday_bids)

        if highest_prev_bid >= DAILY_SALARY * 0.8:
            current_bid = DAILY_SALARY * 0.8 # Bid high to compete
        elif highest_prev_bid >= DAILY_SALARY * 0.6:
            current_bid = max(current_bid, highest_prev_bid * 1.05) # Try to slightly outbid
        else:
            current_bid = max(current_bid, avg_prev_bid + 2) # Bid slightly above average

    # Adjust for my HP if moderately low (not critical, but needs attention)
    if my_status['hp'] <= MODERATE_HP_THRESHOLD and my_status['hp'] > CRITICAL_HP_THRESHOLD:
        current_bid = max(current_bid, DAILY_SALARY * 0.7)

    # Ensure bid is at least a reasonable amount to secure water (e.g., cost of ~1 unit water)
    min_effective_bid_floor = DAILY_SALARY / WATER_REQ * 1.5
    current_bid = max(current_bid, min_effective_bid_floor)

    # Cap the bid at a reasonable maximum unless in critical state
    current_bid = min(current_bid, DAILY_SALARY * 0.9)

    return min(my_status['budget'], current_bid)
